    "name": "Consentimiento informado de implantes con ácido poliláctico",
    "title": "Consentimiento informado de implantes con ácido poliláctico",
    "description": "Texto extenso saneado desde el PDF aportado por BS Medical para tratamientos de estética, medicina estética o cirugía.",
    "purpose": "clinical",
    "blocking_policy": "hard",
    "validity_mode": "single_act",
